SELECT h.id, h.uid, h.vid, h.view_time, h.duration, h.is_finish, h.device, h.ip, h.is_delete FROM bh_video h WHERE h.uid = #{queryVo.uid} AND h.is_delete = 0
AND h.view_time >= #{queryVo.startTime}
AND h.view_time <= #{queryVo.endTime}
ORDER BY h.view_time DESC

